const body = $json.body || {};
const projectId = body.projectId || null;
const code = Number(body.code || 0);
const videos = Array.isArray(body.videos) ? body.videos : [];

return [{
  json: {
    code,
    projectId,
    projectName: body.projectName || '',
    creditsUsed: body.creditsUsed ?? null,
    videos
  }
}];

// Combina dados do webhook com metadados do banco
const webhook = $('normalize-webhook-payload').item.json;
const meta = $('fetch-video-metadata').item?.json || {};

return [{
  json: {
    projectId: webhook.projectId,
    projectName: webhook.projectName,
    creditsUsed: webhook.creditsUsed,
    // metadados do banco
    video_origem_id: meta.video_origem_id || '',
    canal_id: meta.canal_id || '',
    titulo_original: meta.titulo_original || webhook.projectName || '',
    nome_canal: meta.nome_canal || 'Canal',
    nicho: meta.nicho || 'geral',
    tom_de_voz: meta.tom_de_voz || 'informal e engajador',
    // clips do vizard
    videos: webhook.videos || []
  }
}];

// Explode clips e injeta metadados do vídeo/canal em cada um
// Também renomeia campos do Vizard para o padrão interno
const data = $json;
const videos = data.videos || [];

return videos.map(v => ({
  json: {
    // metadados do banco (iguais pra todos os clips)
    projectId: data.projectId,
    video_origem_id: data.video_origem_id,
    canal_id: data.canal_id,
    titulo_original: data.titulo_original,
    nome_canal: data.nome_canal,
    nicho: data.nicho,
    tom_de_voz: data.tom_de_voz,
    // dados do clip Vizard (renomeados para padrão interno)
    vizard_video_id: v.videoId ? String(v.videoId) : '',
    clip_url: v.videoUrl || '',
    clip_editor_url: v.clipEditorUrl || '',
    titulo_sugerido: v.title || '',
    transcricao: v.transcript || '',
    score: Number(v.viralScore || 0),
    viral_reason: v.viralReason || '',
    duracao: Math.round((v.videoMsDuration || 0) / 1000),
    related_topic: v.relatedTopic || ''
  }
}));

